from .models import Item, Order
from .store import Store


def line_total(item: Item, qty: int) -> int:
    """Cents for `qty` units of `item`."""
    return item.price_cents * qty


def order_total(store: Store, order: Order) -> int:
    """Cents for the whole order."""
    return sum(line_total(store.get(sku), qty) for sku, qty in order.lines)

