from .store import Store


def low_stock(store: Store, threshold: int) -> list[str]:
    """SKUs whose quantity is below `threshold`, by SKU."""
    return [i.sku for i in store.list_items() if i.qty < threshold]


def csv_export(store: Store) -> str:
    """One line per item: sku,name,qty,price_cents (with a header)."""
    lines = ["sku,name,qty,price_cents"]
    for i in store.list_items():
        lines.append(f"{i.sku},{i.name},{i.qty},{i.price_cents}")
    return "\n".join(lines) + "\n"

