from .models import Item, Order


class Store:
    """In-memory stock, keyed by SKU."""

    def __init__(self) -> None:
        self._items: dict[str, Item] = {}

    def add_item(self, item: Item) -> None:
        if item.sku in self._items:
            raise ValueError(f"duplicate sku {item.sku}")
        if item.qty < 0:
            raise ValueError("qty must not be negative")
        self._items[item.sku] = item

    def get(self, sku: str) -> Item:
        try:
            return self._items[sku]
        except KeyError:
            raise KeyError(f"unknown sku {sku}") from None

    def list_items(self) -> list[Item]:
        return [self._items[s] for s in sorted(self._items)]

    def adjust(self, sku: str, delta: int) -> int:
        """Change the quantity on hand by `delta`; returns the new quantity."""
        item = self.get(sku)
        if item.qty + delta < 0:
            raise ValueError(f"not enough stock for {sku}")
        item.qty += delta
        return item.qty

    def reserve(self, order: Order) -> None:
        """Take every line of `order` out of stock, all or nothing."""
        if order.status != "new":
            raise ValueError(f"order {order.id} is {order.status}")
        for sku, qty in order.lines:
            if self.get(sku).qty < qty:
                raise ValueError(f"not enough stock for {sku}")
        for sku, qty in order.lines:
            self.get(sku).qty -= qty
        order.status = "reserved"
